import json
rows = json.loads(context)
totals = {}
for row in rows:
    day = row['record_date']
    kind = row['account_type']
    if 'Total TGA Deposits' in kind:
        totals.setdefault(day, [0, 0])[0] += int(row['open_today_bal'])
    elif 'Total TGA Withdrawals' in kind:
        totals.setdefault(day, [0, 0])[1] += int(row['open_today_bal'])
print(totals)
print(FINAL(str(sum(deposits - withdrawals for deposits, withdrawals in totals.values()))))
